$$
\begin{aligned}
&\begin{array}{l}
\text { Silver chloride dissolves in excess of } \\
\text { ammonium hydroxide solution. The cation } \\
\text { present in the resulting solution is }\left[\mathrm{Ag}\left(\mathrm{NH}_{3}\right)_{2}\right]^{+} \\
\text {In aqueous solution, silver chloride exist as } \mathrm{Ag}^{+} \\
\text {=and } \mathrm{Cl}^{-} \text {. } \mathrm{Ag}^{+} \text {present in solution reacts with } \mathrm{NH}_{3}
\end{array}\\
&\begin{array}{l}
\text { form }\left[\mathrm{Ag}\left(\mathrm{NH}_{3}\right)_{2}\right]^{+} \\
\mathrm{Ag}^{+} \mathrm{Cl}^{-}+2 \mathrm{NH}_{3} \longrightarrow\left[\mathrm{Ag}\left(\mathrm{NH}_{3}\right)_{2}\right]^{+} \mathrm{Cl}^{-}
\end{array}
\end{aligned}
$$
